    "Read as {0}: its party and names checked out against this ROM. Off: {1}. The library tags it PARTIALLY SUPPORTED." to Tr(ja = "{0}として よみます: てもちと なまえは この ROMと あいました。 オフ: {1}。 ライブラリでは 「いちぶ たいおう」です。", fr = "Lu comme {0} : équipe et noms vérifiés sur cette ROM. Désactivé : {1}. La bibliothèque l'indique PARTIEL.", de = "Gelesen als {0}: Team und Namen passen zu diesem ROM. Aus: {1}. Die Bibliothek markiert es als TEILWEISE.", it = "Letto come {0}: squadra e nomi verificati su questa ROM. Spento: {1}. La libreria lo segna PARZIALE.", es = "Leído como {0}: equipo y nombres comprobados en esta ROM. Desactivado: {1}. La biblioteca lo marca PARCIAL.", br = "Lido como {0}: equipe e nomes verificados nesta ROM. Desativado: {1}. A biblioteca o marca como PARCIAL.", pt = "Lido como {0}: equipe e nomes verificados nesta ROM. Desativado: {1}. A biblioteca marca-o como PARCIAL."),
