    "Marks {0} as out of the run, as if it had fainted." to Tr(ja = "{0}が たおれた ことに して もう つかえなく します。", fr = "Retire {0} du défi, comme s'il avait été mis K.O.", de = "Lässt {0} ausscheiden, als wäre es besiegt worden.", it = "Mette {0} fuori dalla sfida, come se fosse esausto.", es = "Saca a {0} del reto, como si se hubiera debilitado.", br = "Tira {0} do desafio, como se tivesse desmaiado.", pt = "Tira {0} do desafio, como se tivesse desmaiado."),
    "ENCOUNTERS" to Tr(ja = "であい", fr = "RENCONTRES", de = "BEGEGNUNGEN", it = "INCONTRI", es = "ENCUENTROS", br = "ENCONTROS", pt = "ENCONTROS"),
    "GRAVEYARD" to Tr(ja = "おはか", fr = "CIMETIÈRE", de = "FRIEDHOF", it = "CIMITERO", es = "CEMENTERIO", br = "CEMITÉRIO", pt = "CEMITÉRIO"),
    "Fainted in {0}" to Tr(ja = "{0}で たおれた", fr = "K.O. à {0}", de = "Besiegt in {0}", it = "Esausto a {0}", es = "Debilitado en {0}", br = "Desmaiou em {0}", pt = "Desmaiou em {0}"),
    "BRING BACK {0}?" to Tr(ja = "{0}を もどす?", fr = "RAMENER {0} ?", de = "{0} ZURÜCKHOLEN?", it = "RIPORTARE {0}?", es = "¿RECUPERAR A {0}?", br = "TRAZER {0} DE VOLTA?", pt = "TRAZER {0} DE VOLTA?"),
    "Puts {0} back in the run, for a faint that shouldn't count." to Tr(ja = "かぞえない はずの ひんしなら {0}を もどします。", fr = "Remet {0} dans le défi, pour un K.O. qui ne devrait pas compter.", de = "Holt {0} in den Lauf zurück, für eine Niederlage, die nicht zählen soll.", it = "Rimette {0} nella sfida, per un esausto che non deve contare.", es = "Devuelve a {0} al reto, por un debilitamiento que no debería contar.", br = "Põe {0} de volta no desafio, para um desmaio que não devia contar.", pt = "Põe {0} de volta no desafio, para um desmaio que não devia contar."),
