    "A POKéMON you've caught before doesn't use up an area" to Tr(ja = "つかまえた ことの ある ポケモンは かぞえない", fr = "Un POKéMON déjà capturé n'utilise pas la zone", de = "Ein schon gefangenes POKéMON verbraucht kein Gebiet", it = "Un POKéMON già catturato non consuma la zona", es = "Un POKéMON ya capturado no gasta la zona", br = "Um POKéMON já capturado não gasta a área", pt = "Um POKéMON já capturado não gasta a área"),
    "WARNINGS" to Tr(ja = "おしらせ", fr = "AVERTISSEMENTS", de = "HINWEISE", it = "AVVISI", es = "AVISOS", br = "AVISOS", pt = "AVISOS"),
    "Notices on the game screen as the run goes" to Tr(ja = "ゲームの がめんに おしらせを だす", fr = "Des messages sur l'écran du jeu pendant le défi", de = "Hinweise auf dem Spielbildschirm", it = "Messaggi sullo schermo del gioco durante la sfida", es = "Avisos en la pantalla del juego durante el reto", br = "Avisos na tela do jogo durante o desafio", pt = "Avisos no ecrã do jogo durante o desafio"),
    "NEW RUN" to Tr(ja = "あたらしく はじめる", fr = "NOUVEAU DÉFI", de = "NEUER LAUF", it = "NUOVA SFIDA", es = "NUEVO RETO", br = "NOVO DESAFIO", pt = "NOVO DESAFIO"),
    "NEW RUN?" to Tr(ja = "あたらしく はじめる?", fr = "NOUVEAU DÉFI ?", de = "NEUER LAUF?", it = "NUOVA SFIDA?", es = "¿NUEVO RETO?", br = "NOVO DESAFIO?", pt = "NOVO DESAFIO?"),
    "Forgets every encounter and fainted POKéMON of this run. Your party right now starts the new one." to Tr(ja = "この チャレンジの であいと たおれた ポケモンを すべて わすれます。いまの てもちで あたらしく はじめます。", fr = "Oublie toutes les rencontres et les POKéMON K.O. de ce défi. Votre équipe actuelle commence le nouveau.", de = "Vergisst alle Begegnungen und besiegten POKéMON dieses Laufs. Dein jetziges Team beginnt den neuen.", it = "Dimentica tutti gli incontri e i POKéMON esausti di questa sfida. La tua squadra attuale inizia la nuova.", es = "Olvida todos los encuentros y POKéMON debilitados de este reto. Tu equipo actual empieza el nuevo.", br = "Esquece todos os encontros e POKéMON desmaiados deste desafio. Sua equipe atual começa o novo.", pt = "Esquece todos os encontros e POKéMON desmaiados deste desafio. A tua equipa atual começa o novo."),
    "PKMN DATA" to Tr(ja = "ポケモン データ", fr = "DONNÉES PKMN", de = "PKMN-DATEN", it = "DATI PKMN", es = "DATOS PKMN", br = "DADOS PKMN", pt = "DADOS PKMN"),
    "Swap {0} with which POKéMON?" to Tr(ja = "{0}と どの ポケモンを いれかえる?", fr = "Échanger {0} avec quel POKéMON ?", de = "{0} mit welchem POKéMON tauschen?", it = "Scambiare {0} con quale POKéMON?", es = "¿Cambiar {0} por qué POKéMON?", br = "Trocar {0} com qual POKéMON?", pt = "Trocar {0} com qual POKéMON?"),
    "{0} joined the party and {1} went to {2}. Save in the game to keep it." to Tr(ja = "{0}が てもちに くわわり {1}は {2}へ。 のこすには ゲームで レポートを かいてね。", fr = "{0} rejoint l'équipe et {1} va dans {2}. Sauvegardez dans le jeu pour le garder.", de = "{0} ist jetzt im Team, {1} in {2}. Speichere im Spiel, um es zu behalten.", it = "{0} entra in squadra e {1} va in {2}. Salva nel gioco per tenerlo.", es = "{0} se une al equipo y {1} va a {2}. Guarda en el juego para conservarlo.", br = "{0} entrou na equipe e {1} foi para {2}. Salve no jogo para manter.", pt = "{0} entrou na equipa e {1} foi para {2}. Guarda no jogo para manter."),
    "The party or the box has changed. Try again." to Tr(ja = "てもちか ボックスが かわりました。 もういちど ためしてね。", fr = "L'équipe ou la boîte a changé. Réessayez.", de = "Team oder Box haben sich geändert. Versuch es noch mal.", it = "La squadra o il box sono cambiati. Riprova.", es = "El equipo o la caja ha cambiado. Inténtalo de nuevo.", br = "A equipe ou a caixa mudou. Tente de novo.", pt = "A equipa ou a caixa mudou. Tenta de novo."),
    "Take the MAIL from {0} first." to Tr(ja = "さきに {0}の メールを はずしてね。", fr = "Retirez d'abord la LETTRE de {0}.", de = "Nimm {0} zuerst den BRIEF ab.", it = "Togli prima la LETTERA a {0}.", es = "Quítale antes la CARTA a {0}.", br = "Tire a CARTA de {0} primeiro.", pt = "Tira a CARTA de {0} primeiro."),
    "An EGG can't take the place of your last POKéMON that can battle." to Tr(ja = "たたかえる さいごの ポケモンと タマゴは いれかえられない。", fr = "Un ŒUF ne peut pas remplacer votre dernier POKéMON en état de se battre.", de = "Ein EI kann dein letztes kampffähiges POKéMON nicht ersetzen.", it = "Un UOVO non può prendere il posto del tuo ultimo POKéMON in grado di lottare.", es = "Un HUEVO no puede ocupar el lugar de tu último POKéMON que puede luchar.", br = "Um OVO não pode tomar o lugar do seu último POKéMON que pode batalhar.", pt = "Um OVO não pode tomar o lugar do teu último POKéMON que pode lutar."),
    "The swap didn't work. Nothing was changed." to Tr(ja = "いれかえられなかった。 なにも かわっていません。", fr = "L'échange n'a pas marché. Rien n'a changé.", de = "Der Tausch hat nicht geklappt. Nichts wurde geändert.", it = "Lo scambio non è riuscito. Non è cambiato nulla.", es = "El cambio no ha funcionado. No se ha cambiado nada.", br = "A troca não funcionou. Nada foi alterado.", pt = "A troca não funcionou. Nada foi alterado."),
    "Pick a box" to Tr(ja = "ボックスを えらぶ", fr = "Choisir une boîte", de = "Box wählen", it = "Scegli un box", es = "Elegir una caja", br = "Escolher uma caixa", pt = "Escolher uma caixa"),
    "NUZLOCKE" to Tr(ja = "ナズロック", fr = "NUZLOCKE", de = "NUZLOCKE", it = "NUZLOCKE", es = "NUZLOCKE", br = "NUZLOCKE", pt = "NUZLOCKE"),
    "{0} ALIVE · {1} FAINTED" to Tr(ja = "げんき {0} · ひんし {1}", fr = "{0} EN VIE · {1} TOMBÉS", de = "{0} FIT · {1} BESIEGT", it = "{0} VIVI · {1} CADUTI", es = "{0} EN PIE · {1} CAÍDOS", br = "{0} VIVOS · {1} CAÍDOS", pt = "{0} VIVOS · {1} CAÍDOS"),
    "NOT USED" to Tr(ja = "つかって いない", fr = "NON UTILISÉ", de = "UNBENUTZT", it = "NON USATO", es = "SIN USAR", br = "NÃO USADO", pt = "NÃO USADO"),
    "With you from the start" to Tr(ja = "さいしょから いっしょ", fr = "Avec vous depuis le début", de = "Von Anfang an dabei", it = "Con te dall'inizio", es = "Contigo desde el principio", br = "Com você desde o início", pt = "Contigo desde o início"),
    "Joined in {0}" to Tr(ja = "{0}で なかまに なった", fr = "Arrivé à {0}", de = "Dazugekommen in {0}", it = "Arrivato a {0}", es = "Se unió en {0}", br = "Entrou em {0}", pt = "Entrou em {0}"),
    "Out of the run" to Tr(ja = "もう つかえない", fr = "Hors du défi", de = "Ausgeschieden", it = "Fuori dalla sfida", es = "Fuera del reto", br = "Fora do desafio", pt = "Fora do desafio"),
    "Track a run: one catch per area, a faint is final" to Tr(ja = "1ばしょ 1ぴき、ひんしは さいごの チャレンジを きろく", fr = "Suivez un défi : une capture par zone, un K.O. est définitif", de = "Verfolge einen Lauf: ein Fang pro Gebiet, besiegt ist endgültig", it = "Segui una sfida: una cattura per zona, chi è esausto è perso", es = "Sigue un reto: una captura por zona, debilitarse es definitivo", br = "Acompanhe um desafio: uma captura por área, desmaiar é para sempre", pt = "Acompanha um desafio: uma captura por área, desmaiar é para sempre"),
    // Feature tips (FeatureTip.kt): the card over the game / on the companion.
    "ZOOM OUT, LOOK AROUND" to Tr(ja = "ズームして みまわそう", fr = "DÉZOOMEZ, REGARDEZ AUTOUR", de = "HERAUSZOOMEN, UMSEHEN", it = "ALLONTANA E GUARDATI INTORNO", es = "ALEJA Y MIRA ALREDEDOR", br = "AFASTE E OLHE AO REDOR", pt = "AFASTE E OLHE À VOLTA"),
    "With EXPAND you can see further than the game ever showed you." to Tr(ja = "ひろげる なら ゲームが みせなかった ところまで みえる。", fr = "Avec ÉTENDRE, vous voyez plus loin que le jeu ne l'a jamais montré.", de = "Mit ERWEITERN siehst du weiter, als das Spiel je gezeigt hat.", it = "Con ESPANDI vedi più lontano di quanto il gioco abbia mai mostrato.", es = "Con AMPLIAR ves más lejos de lo que el juego mostró nunca.", br = "Com EXPANDIR você vê mais longe do que o jogo já mostrou.", pt = "Com EXPANDIR vê mais longe do que o jogo alguma vez mostrou."),
    "SHOW ME" to Tr(ja = "みせて", fr = "MONTRER", de = "ZEIG MAL", it = "MOSTRA", es = "VER", br = "MOSTRAR", pt = "MOSTRAR"),
    "SEE MORE OF THE WORLD" to Tr(ja = "せかいを もっと みよう", fr = "VOYEZ PLUS DU MONDE", de = "SIEH MEHR VON DER WELT", it = "VEDI PIÙ MONDO", es = "VE MÁS DEL MUNDO", br = "VEJA MAIS DO MUNDO", pt = "VEJA MAIS DO MUNDO"),
    "EXPAND draws the map past the game's edges, so the whole screen is the game. No black bars, nothing stretched." to Tr(ja = "ひろげるは ゲームの はしの そとまで マップを えがく。 がめん ぜんぶが ゲームに なる。 くろい おびも のびも なし。", fr = "ÉTENDRE dessine la carte au-delà des bords du jeu : tout l'écran devient le jeu. Ni bandes noires, ni étirement.", de = "ERWEITERN zeichnet die Karte über den Rand des Spiels hinaus, der ganze Bildschirm ist Spiel. Keine schwarzen Balken, nichts verzerrt.", it = "ESPANDI disegna la mappa oltre i bordi del gioco: tutto lo schermo è il gioco. Niente bande nere, niente stirato.", es = "AMPLIAR dibuja el mapa más allá de los bordes del juego: toda la pantalla es el juego. Sin barras negras ni estirar.", br = "EXPANDIR desenha o mapa além das bordas do jogo: a tela toda é o jogo. Sem barras pretas, nada esticado.", pt = "EXPANDIR desenha o mapa para lá das margens do jogo: o ecrã todo é o jogo. Sem barras pretas, nada esticado."),
    "EVERYTHING IN ONE PRESS" to Tr(ja = "ボタン ひとつで なんでも", fr = "TOUT EN UNE PRESSION", de = "ALLES MIT EINEM DRUCK", it = "TUTTO CON UN TASTO", es = "TODO CON UN BOTÓN", br = "TUDO NUM BOTÃO", pt = "TUDO NUM BOTÃO"),
    "The QUICK MENU opens the PC, flies, gets on your bike or saves a state without leaving the field." to Tr(ja = "クイックメニューで パソコン そらをとぶ じてんしゃ ステート セーブが その ばで できる。", fr = "Le MENU RAPIDE ouvre le PC, fait voler, sort le vélo ou sauve un état sans quitter la carte.", de = "Das SCHNELLMENÜ öffnet den PC, fliegt, holt das Rad oder sichert einen Spielstand, direkt unterwegs.", it = "Il MENU RAPIDO apre il PC, vola, prende la bici o salva uno stato senza lasciare la mappa.", es = "El MENÚ RÁPIDO abre el PC, vuela, saca la bici o guarda un estado sin salir del mapa.", br = "O MENU RÁPIDO abre o PC, voa, pega a bicicleta ou salva um estado sem sair do mapa.", pt = "O MENU RÁPIDO abre o PC, voa, tira a bicicleta ou guarda um estado sem sair do mapa."),
    "OPEN IT" to Tr(ja = "ひらく", fr = "OUVRIR", de = "ÖFFNEN", it = "APRI", es = "ABRIR", br = "ABRIR", pt = "ABRIR"),
    "TAP THE HUD" to Tr(ja = "HUDを タッチ", fr = "TOUCHEZ LE HUD", de = "TIPP AUFS HUD", it = "TOCCA L'HUD", es = "TOCA EL HUD", br = "TOQUE NO HUD", pt = "TOQUE NO HUD"),
    "Tap a party icon for its summary, the minimap for the map, BAG to use an item." to Tr(ja = "てもちの アイコンで ようす ミニマップで マップ バッグで どうぐを つかえる。", fr = "Touchez une icône de l'équipe pour son résumé, la mini carte pour la carte, SAC pour utiliser un objet.", de = "Tipp ein Teamsymbol für die Übersicht, die Minikarte für die Karte, BEUTEL für ein Item.", it = "Tocca un'icona della squadra per il riepilogo, la minimappa per la mappa, BORSA per usare uno strumento.", es = "Toca un icono del equipo para su resumen, el minimapa para el mapa, MOCHILA para usar un objeto.", br = "Toque num ícone da equipe para o resumo, no minimapa para o mapa, em MOCHILA para usar um item.", pt = "Toque num ícone da equipe para o resumo, no minimapa para o mapa, em MOCHILA para usar um item."),
    "THE PC, FROM ANYWHERE" to Tr(ja = "どこでも パソコン", fr = "LE PC, OÙ QUE VOUS SOYEZ", de = "DER PC, ÜBERALL", it = "IL PC, OVUNQUE", es = "EL PC, DONDE SEA", br = "O PC, DE QUALQUER LUGAR", pt = "O PC, EM QUALQUER LADO"),
    "Open your boxes from the BAG tab or the QUICK MENU. No walk back to town." to Tr(ja = "バッグか クイックメニューから ボックスを ひらける。 まちまで もどらなくて いい。", fr = "Ouvrez vos boîtes depuis l'onglet SAC ou le MENU RAPIDE. Plus besoin de rentrer en ville.", de = "Öffne deine Boxen über BEUTEL oder das SCHNELLMENÜ. Kein Weg zurück in die Stadt.", it = "Apri i box dalla scheda BORSA o dal MENU RAPIDO. Niente ritorno in città.", es = "Abre tus cajas desde MOCHILA o el MENÚ RÁPIDO. Sin volver a la ciudad.", br = "Abra suas caixas pela MOCHILA ou pelo MENU RÁPIDO. Sem voltar à cidade.", pt = "Abra as suas caixas pela MOCHILA ou pelo MENU RÁPIDO. Sem voltar à cidade."),
    "OPEN PC" to Tr(ja = "パソコンを ひらく", fr = "OUVRIR LE PC", de = "PC ÖFFNEN", it = "APRI IL PC", es = "ABRIR PC", br = "ABRIR PC", pt = "ABRIR PC"),
    "NO NEED TO HOLD B" to Tr(ja = "Bを おさなくて いい", fr = "PLUS BESOIN DE TENIR B", de = "B NICHT MEHR HALTEN", it = "NON SERVE TENERE B", es = "SIN MANTENER B", br = "SEM SEGURAR B", pt = "SEM MANTER B"),
    "AUTO-RUN makes you run on the field by itself. Hold B when you want to walk." to Tr(ja = "オートダッシュで いつでも はしる。 あるきたい ときは Bを おす。", fr = "COURSE AUTO vous fait courir tout seul. Maintenez B pour marcher.", de = "AUTO-RENNEN lässt dich von selbst rennen. Halte B, um zu gehen.", it = "CORSA AUTO ti fa correre da solo. Tieni premuto B per camminare.", es = "CORRER AUTO te hace correr solo. Mantén B para caminar.", br = "CORRIDA AUTO faz você correr sozinho. Segure B para andar.", pt = "CORRIDA AUTO faz você correr sozinho. Mantenha B para andar."),
    "TIRED OF WILD BATTLES?" to Tr(ja = "やせいの バトルに つかれた?", fr = "MARRE DES COMBATS SAUVAGES ?", de = "GENUG VON WILDEN KÄMPFEN?", it = "STANCO DEI SELVATICI?", es = "¿HARTO DE LOS SALVAJES?", br = "CANSADO DE BATALHAS SELVAGENS?", pt = "FARTO DE BATALHAS SELVAGENS?"),
    "Switch wild encounters off for a while. Fishing and story battles still happen." to Tr(ja = "やせいの ポケモンを しばらく オフに。 つりと イベントの バトルは そのまま。", fr = "Coupez les POKéMON SAUVAGES un moment. La pêche et les combats de l'histoire restent.", de = "Schalte WILDE POKéMON eine Weile ab. Angeln und Kämpfe der Geschichte bleiben.", it = "Spegni i POKéMON SELVATICI per un po'. Pesca e lotte della storia restano.", es = "Apaga los POKéMON SALVAJES un rato. La pesca y los combates de la historia siguen.", br = "Desligue os POKéMON SELVAGENS por um tempo. Pesca e batalhas da história continuam.", pt = "Desligue os POKéMON SELVAGENS por um tempo. Pesca e batalhas da história continuam."),
    "SWITCH OFF" to Tr(ja = "オフにする", fr = "COUPER", de = "ABSCHALTEN", it = "SPEGNI", es = "APAGAR", br = "DESLIGAR", pt = "DESLIGAR"),
    "KEEP YOUR TMS" to Tr(ja = "わざマシンを なくさない", fr = "GARDEZ VOS CT", de = "BEHALTE DEINE TM", it = "TIENI LE MT", es = "CONSERVA TUS MT", br = "GUARDE SEUS MTs", pt = "GUARDE OS SEUS MTs"),
    "With REUSABLE TMS a TM stays in your bag after it teaches a move." to Tr(ja = "マシン むげん なら おしえた あとも わざマシンが バッグに のこる。", fr = "Avec CT ILLIMITÉES, une CT reste dans le sac après usage.", de = "Mit TM BLEIBEN bleibt eine TM nach dem Lehren im Beutel.", it = "Con MT ILLIMITATE una MT resta nella borsa dopo l'uso.", es = "Con MT ILIMITADAS una MT sigue en la mochila tras usarla.", br = "Com MT ILIMITADOS um MT fica na mochila depois de usado.", pt = "Com MT ILIMITADOS um MT fica na mochila depois de usado."),
    "FLY WITHOUT THE MENUS" to Tr(ja = "メニュー なしで そらをとぶ", fr = "VOLER SANS LES MENUS", de = "FLIEGEN OHNE MENÜS", it = "VOLA SENZA MENU", es = "VUELA SIN MENÚS", br = "VOE SEM MENUS", pt = "VOE SEM MENUS"),
    "Pick a town you've been to and fly there: FLY on the MAP, or in the QUICK MENU." to Tr(ja = "いった まちを えらんで ひとっとび。 マップか クイックメニューの そらをとぶで。", fr = "Choisissez une ville déjà visitée et volez-y : VOL sur la CARTE ou dans le MENU RAPIDE.", de = "Wähle eine besuchte Stadt und flieg hin: FLIEGEN auf der KARTE oder im SCHNELLMENÜ.", it = "Scegli una città già visitata e volaci: VOLO sulla MAPPA o nel MENU RAPIDO.", es = "Elige una ciudad visitada y vuela allí: VUELO en el MAPA o en el MENÚ RÁPIDO.", br = "Escolha uma cidade visitada e voe até lá: VOAR no MAPA ou no MENU RÁPIDO.", pt = "Escolha uma cidade visitada e voe até lá: VOAR no MAPA ou no MENU RÁPIDO."),
    "FLY NOW" to Tr(ja = "そらをとぶ", fr = "VOLER", de = "FLIEGEN", it = "VOLA", es = "VOLAR", br = "VOAR", pt = "VOAR"),
    "RIGHT STICK" to Tr(ja = "みぎスティック", fr = "STICK DROIT", de = "RECHTER STICK", it = "STICK DESTRO", es = "STICK DERECHO", br = "ANALÓGICO DIREITO", pt = "ANALÓGICO DIREITO"),
    "LOOK AROUND" to Tr(ja = "みまわす", fr = "REGARDER", de = "UMSEHEN", it = "GUARDA INTORNO", es = "MIRAR", br = "OLHAR", pt = "OLHAR"),
